/** 9:00 AM WAT on the published date; articles without a date are already live. */
export function isArticleLive(a: Article, now: number = Date.now()): boolean {
  if (!a.published) return true;
  return new Date(`${a.published}T09:00:00+01:00`).getTime() <= now;
}

/** Articles visible to the public right now (future-dated ones are hidden). */
export function liveArticles(now: number = Date.now()): Article[] {
  return articles.filter((a) => isArticleLive(a, now));
}
